#!/usr/bin/env python3
"""Feature-agent prompts for one coverage wave.

    wave-prompts.py <wave-dir> <suffix>

Writes <wave-dir>/prompt-<agent>.txt for each agent in OWNS. Edit OWNS
(one line per agent: what it owns, shown to every agent) and EXTRA (the
agent's own priorities) per wave; the agent names must match the table
in wave-lists.py. <suffix> is appended to branch names so they do not
clash with an earlier wave's branches.
"""
import sys

W, SUF = sys.argv[1], sys.argv[2]
OWNS = {
    'template': 'the template author (`crates/mtg-cards/src/author.rs`) and the phrases it needs: cards whose draft fails to parse or renders with a mismatch, and regular sentences the author still skips although the card language can say them',
    'wording': 'cards a card agent reported as a renderer near-miss (`RENDER:`) or as gating with the wrong meaning (`MEANING:`): renderer wording, and binding of pronouns and references in the compiler',
    'transform-mana': 'double-faced cards, "becomes" effects and land animation; and mana: restricted mana for ability kinds and spell properties, conditions on the mana spent, delayed and unusual mana production',
    'counters-costs': 'counters (kinds, moving, removing, "for each counter", triggers on counters) and costs (additional and alternative costs, "reveal a card from your hand" as a cost, taxes, "unless its controller pays", sacrifice and discard costs, {Q})',
    'library': 'library and hand forms: look at / reveal / search / shuffle forms, dig splits, top-card effects, scry and mill variants, hand reveals and "player reveals, you choose"',
    'graveyard-exile': 'graveyard and exile forms: cast or play from another zone, linked exile and its returns, exile-until, graveyard-order and graveyard-targeting rules, and copying of spells and permanents',
    'triggers': 'triggered abilities, their conditions and delayed triggers, and replacement and prevention effects still reported missing',
    'rules': 'combat, targets, filters, counts, durations, static abilities and player-choice effects still reported missing, and anything no other agent owns',
}
PAUPER = 'Pauper is the first coverage target and needs 197 more cards for 95%; every agent this wave works its Pauper lines first, card by card where no group exists, then Standard, then groups of Modern cards.'
EXTRA = {
    'template': PAUPER + """ The template author costs nothing to run afterwards, so every form it learns pays in all three pools. In order: (1) the parse failures and mismatches on your list, grouped by the phrase that fails (the list is sorted Pauper first; `author --format <f> --verbose` reproduces it); (2) the commonest `sentence:` skip reasons in `{W}/backlog-ranked.tsv` that are only a template or phrase away (not ones another agent owns below). After each change run the author on all three formats and verify each newly written card with a scenario before adding it (do not run `--write` over a whole format).""",
    'wording': PAUPER + """ Each line on your list says what the renderer printed and what the Oracle text says, or which reference bound to the wrong object. These are the cheapest cards in the backlog: the engine can usually already do what the card does. For a `RENDER:` line fix the renderer (or add the alternative phrase to the parser) and write the card with a scenario. For a `MEANING:` line make the compiler bind the form correctly, or reject it, and add a scenario that checks the amount or the object. Any form you cannot fix goes in your notes under `New` with the form that works instead. Many lines are from earlier waves and may already be fixed: try the card first.""",
    'transform-mana': PAUPER + """ Left by last wave's branches (see `KNOWN-ISSUES.md` section 3): restricted mana for ability kinds and spell properties (power-up, equip, cast from exile or graveyard, kicked, face-down, {X} costs, Class level), "and that spell can't be countered" (Cavern of Souls), conditions on the mana spent (Tokka & Rahzar, Unravel), delayed mana ("add {R} at the beginning of your next main phase"), conditional transforms, "all creature types" in an indefinite becomes. The mana pool is on the hot path: keep payment as cheap as it is when no card in the game makes restricted mana, and compare `target/release/mtg sim --deck1 random:3 --deck2 random:4 --games 500 --seed 5` before and after a pool change: the `wins` line must not change.""",
    'counters-costs': PAUPER + """ Your list is long. Read it, group the reports by what is missing, and build the groups in order of Pauper plus Standard cards unlocked; "As an additional cost to cast this spell, [you may] reveal a <type> card from your hand" is about 20 cards. Also yours (`KNOWN-ISSUES.md` section 2): a `pay x life` activated cost pays nothing (Krumar Initiate).""",
    'library': PAUPER + """ Your list is long (most of it Modern cards the template author skips at a library sentence). Read the Pauper and Standard lines, group by what is missing, and build the groups in order of cards unlocked; teach the template author each regular sentence so the Modern lines follow without your writing them (run the author afterwards and verify what it writes with scenarios). Known gaps: opening-hand reveals, three-way dig splits, searches for up to X cards, a dig for "mana value X" (Hatchery Spider, `KNOWN-ISSUES.md` section 2), "revealed this way" (Madcap Experiment).""",
    'graveyard-exile': PAUPER + """ Your list is long (most of it Modern cards the template author skips at a graveyard or exile sentence). Read the Pauper and Standard lines, group by what is missing, and build the groups in order of cards unlocked; teach the template author each regular sentence so the Modern lines follow. Known gaps: linked-exile returns, casting a card as an effect while paying its cost (Tinybones, Boiling Rock Rioter), milled or graveyard cards put onto the battlefield (Random Encounter, Bonny Pall), "pay {0} for the first exile cast each turn", "Cards in graveyards can't be the targets of spells or abilities".""",
    'triggers': PAUPER + """ Read your Pauper and Standard lines, group by what is missing, and build the groups in order of cards unlocked. Known gaps: conditions "scried or surveilled this turn", "two or more creatures entered this turn", "if a Rat is attacking"; a leaves-the-battlefield trigger granted by a permanent that leaves at the same time (`KNOWN-ISSUES.md` section 1); "If a creature an opponent controls would die, exile it instead"; delayed triggers of kinds not yet built. A check added for every event must cost nothing when no card in the game uses it.""",
    'rules': PAUPER + """ Read your Pauper lines, then the Standard ones, group the reports by what is missing, and build the groups in order of cards unlocked. Known gaps: changing a spell's target (Return the Favor), "choose up to one target" and what follows it, non-targeting "choose a creature you control", filters "you own", "spell you control", "with {X} in its mana cost", "target spell, activated ability, or triggered ability", "nonattacking", two static abilities on one Oracle line, setting a life total, "You may choose not to untap this creature during your untap step", "assign its combat damage as though it weren't blocked". A count used in a static ability must work in the layer system too (`per_count` in `crates/mtg-core/src/layers.rs` must read `Work`, never `GameState::characteristics`: a debug build panics on re-entry), and `CountExpr::in_static` must classify every count you add.""",
}
for k in OWNS:
    o = '\n'.join(f'- {n}: {d}' + (' (you)' if n == k else '') for n, d in OWNS.items())
    b = f'feature-{k}{SUF}'
    p = f"""You are a feature agent on a Rust Magic: The Gathering rules engine. Your worktree may have been created from an old commit: first run `git checkout -B {b} main` so you start from current main (if git refuses because the branch is checked out in another worktree, use `{b}-b` and say so). Then read `scripts/coverage/feature-brief.md` in your working directory (your git worktree) and follow it exactly. Your notes file (see its section on known issues) is `{W}/notes-{k}.md`.

YOUR ASSIGNMENT (branch name `{b}`): {OWNS[k]}.

{EXTRA[k].replace('{W}', W)}

Your card list is `{W}/lists/{k}.tsv` (card name, formats, and what a card-authoring agent or the template author reported, Pauper cards first, then Standard; a card may need other things too: skip those and say which). Many lines are from earlier waves and may work now. `cargo run -q --release -p mtg-cards -- author --format pauper --verbose` (and `standard`, `modern`; give the modern run a long timeout) lists skipped cards with reasons. Where the wording is regular, add a template to `crates/mtg-cards/src/author.rs`. Do not add the cards named in `{W}/batches/all.txt`: card agents are writing those on main.

OTHER AGENTS working in parallel own these; do not build your own version of any of them, skip cards needing them and say so:
{o}
- eight card-authoring agents are adding new card files under `cards/` and `scenarios/agents/` on main

A card counts only if the gate says Match AND a scenario shows it behaves as the Oracle text says, checking amounts and targets. If a form gates Match but means the wrong thing, do not add the card; put it in your notes file under `New`.
Each new form needs DSL syntax, exact Oracle rendering, SYNTAX.md, and scenarios.

Merge hazards: if you take a free bit (`DefFlags`, `GameObject::marks`, `CastInfo`) or add a `Keyword` (`Keyword::ALL` has a fixed length) or a `CounterKind` (`CounterKind::NAMED` has a fixed length), say so in your final reply, since another branch may take the same one. If you add a variant to an enum that is matched exhaustively elsewhere (`CountExpr`, `Effect`, `Trigger`) or change a function's signature, say so too. A new way to cast a card from hand must be added to the list behind `CardDef::other_casts` in `CardPool::add`. You may add a line form to the scenario runner (`crates/mtg-scenario`) if a card cannot be tested without it; do not change what an existing line does, and name the addition in your final reply. Throughput matters: a check you add to a hot path (priority, state-based actions, `characteristics`, every event) must cost nothing when no card in the game uses the feature (gate it on a pool- or state-level flag rather than scanning the battlefield).

Commit as you go (one commit per feature or bug). Write each commit message to a file and commit with `git commit -F <file>`. End each commit message with `Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>`. Before your last commit run `cargo fmt`, `cargo clippy -q --workspace`, the gate, the scenarios (release, and once with a debug build: `cargo build -p mtg-cli && target/debug/mtg scenario`), and `timeout 2400 cargo test --workspace` (it includes a format/parse round-trip over the whole corpus). Wrap every cargo test run in `timeout`. Give every long command a `timeout` and never wait on one with an unbounded loop: a game that loops shows up only as silence (`scripts/fuzz-random.sh` kills and reports a run after FUZZ_TIMEOUT seconds). When you wait for a background command, never poll with `pgrep -f "<its command line>"`: that matches the polling shell itself and never ends; wait on the command's exit instead. Delete your worktree's `target/` when everything is committed. Final reply: branch name, commit hashes, what you implemented, number of cards added per item, anything left out, bits, keywords, counter kinds, enum variants or signatures you took or changed, and any ENGINE BUG you found."""
    open(f'{W}/prompt-{k}.txt', 'w').write(p)
    print(k, len(p))
